item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {z} from "zod";
  4	
  5	/**
  6	 * Executor of the method `plan-meeting-brief` (v4, after the third independent review). Assembles
  7	 * the first deliverable only from objects in a usable state, each fact bound to the fingerprint of
  8	 * the object it cites; a conditioned, partial or open object names a gap instead of filling a block.
  9	 * Points for and against the thesis come from the stance each object declared on its facts. The
 10	 * page plan honours the number of pages asked, carries the audience's discriminator, and allows
 11	 * production only once the person confirmed that exact plan. Questions the base already answers
 12	 * are refused whatever the caller says; a question that changes nothing is not asked. A previous
 13	 * version yields a change note instead of a silent rewrite. A block is filled only with facts; a
 14	 * usable object without facts names a gap. A conditioned or open object is carried as an uncovered
 15	 * term so its finding is never silently dropped. A financial figure in a fact carries its unit.
 16	 * Without audience or form the deliverable still goes out and the page plan waits. Points for and
 17	 * against the thesis come from the stance any usable object declared, never from a list of kinds.
 18	 * Only cited objects count as used. A question is asked only after a declared search of the base
 19	 * that found no answer. A fact's unit cannot contradict the fact's own words. This executor plans;
 20	 * the prose of the pages is a model step downstream, never produced here.
 21	 */
 22	const nonEmpty = z.string().trim().min(1);
 23	const identifier = z.string().regex(/^[a-z][a-z0-9_.-]*$/);
 24	const sha256 = z.string().regex(/^[a-f0-9]{64}$/);
 25	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 26	type Anchor = z.infer<typeof anchorSchema>;
 27	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 28	
 29	export const objectKinds = ["debt_ledger", "maturity_wall", "covenants", "reconciliation", "interest_schedule", "scenarios", "exit_costs", "before_after", "company_view", "performance"] as const;
 30	/** States that let an object fill a block; every other state names a gap. */
 31	const USABLE_STATES = new Set(["complete", "resolved", "closes", "declared", "compared", "diagnosed"]);
 32	
 33	export const approvedObjectSchema = z.object({
 34	  id: identifier,
 35	  kind: z.enum(objectKinds),
 36	  state: z.enum(["complete", "resolved", "closes", "declared", "compared", "diagnosed", "conditioned", "incomplete", "partial", "open_divergences", "identity_failed", "blocked"]),
 37	  fingerprint: sha256,
 38	  /** Facts the deliverable may cite; each one is bound to the object's fingerprint and declares its stance on the thesis. */
 39	  headlines: z.array(z.object({text: nonEmpty, stance: z.enum(["for", "against", "neutral"]), objectFingerprint: sha256, /** Unit of any figure the text carries (R$ mil, x, %); required when the text carries a thousands-separated number. */ unit: nonEmpty.nullable().default(null), /** The field of the object the fact quotes, so a fact can be audited against the object it is bound to. */ objectPath: nonEmpty.nullable().default(null)}).strict()).max(12).default([]),
 40	}).strict();
 41	
 42	export const briefRequestSchema = z.object({
 43	  turn: z.number().int().positive(),
 44	  /** The person the material is for first; the others do not change the discriminator. */
 45	  /** Null when the person has not said who the material is for; the deliverable goes out and the plan waits. */
 46	  audience: z.object({primary: nonEmpty, others: z.array(nonEmpty).default([])}).strict().nullable(),
 47	  form: z.enum(["first_deliverable", "internal_briefing", "pitch_pages", "analysis_with_scenarios", "board_deck"]).nullable(),
 48	  pages: z.number().int().positive().nullable().default(null),
 49	  /** What the sponsor said, kept verbatim. */
 50	  sponsorInstruction: z.string().nullable().default(null),
 51	  /** What the instruction left undefined, declared by the caller; the deliverable names it instead of hiding it. */
 52	  undefinedAspects: z.array(z.enum(["thesis", "meeting_type", "format", "audience", "depth"])).default([]),
 53	  confirmedPlanId: z.string().nullable().default(null),
 54	}).strict();
 55	
 56	export const candidateQuestionSchema = z.object({
 57	  id: identifier,
 58	  text: nonEmpty,
 59	  /** Why the answer changes the material; a question without a real reason is not asked. */
 60	  changesTheWork: nonEmpty,
 61	  /** The declared search of the base: which documents were checked and what was found; a question without a search is not asked, and a found answer refuses it. */
 62	  coverage: z.object({searched: z.array(nonEmpty).min(1), answeredBy: anchorSchema.nullable(), answer: nonEmpty.nullable()}).strict().nullable().default(null),
 63	  /** How much the answer changes the material, from the coverage map: lower asks first. */
 64	  priority: z.number().int().nonnegative(),
 65	}).strict();
 66	
 67	export const previousVersionSchema = z.object({
 68	  outputFingerprint: sha256,
 69	  blocks: z.array(z.object({id: identifier, state: z.enum(["filled", "gap"]), objectIds: z.array(identifier)}).strict()),
 70	  objectFingerprints: z.record(identifier, sha256),
 71	}).strict();
 72	
 73	export const briefInputSchema = z.object({
 74	  caseId: nonEmpty,
 75	  request: briefRequestSchema,
 76	  objects: z.array(approvedObjectSchema),
 77	  candidateQuestions: z.array(candidateQuestionSchema).default([]),
 78	  previousVersion: previousVersionSchema.nullable().default(null),
 79	}).strict().superRefine((input, context) => {
 80	  const objectIds = new Set<string>();
 81	  input.objects.forEach((object, index) => {
 82	    if (objectIds.has(object.id)) context.addIssue({code: "custom", path: ["objects", index], message: `duplicate object ${object.id}`});
 83	    objectIds.add(object.id);
 84	    object.headlines.forEach((headline, position) => {
 85	      if (headline.objectFingerprint !== object.fingerprint) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the headline is bound to another fingerprint than the object's`});
 86	      if (headline.unit === null && /\d{1,3}(\.\d{3})+/.test(headline.text)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: a fact with a figure needs its unit`});
 87	      if (headline.unit !== null) {
 88	        const words = headline.text.toLowerCase();
 89	        const unit = headline.unit.toLowerCase();
 90	        const saysThousand = /\bmil\b|thousand/.test(words) && !/milh/.test(words);
 91	        const saysMillion = /milh[õo]es|million/.test(words);
 92	        if (saysThousand && /milh|million/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says thousands and its unit says millions`});
 93	        if (saysMillion && /\bmil\b|thousand/.test(unit) && !/milh/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says millions and its unit says thousands`});
 94	      }
 95	    });
 96	  });
 97	  const questionIds = new Set<string>();
 98	  input.candidateQuestions.forEach((question, index) => {
 99	    if (questionIds.has(question.id)) context.addIssue({code: "custom", path: ["candidateQuestions", index], message: `duplicate question ${question.id}`});
100	    questionIds.add(question.id);
101	    if (question.coverage && (question.coverage.answeredBy === null) !== (question.coverage.answer === null)) context.addIssue({code: "custom", path: ["candidateQuestions", index, "coverage"], message: `${question.id}: an answer and its anchor come together`});
102	  });
103	  const blockIds = new Set<string>();
104	  input.previousVersion?.blocks.forEach((block, index) => {
105	    if (blockIds.has(block.id)) context.addIssue({code: "custom", path: ["previousVersion", "blocks", index], message: `duplicate block ${block.id} in the previous version`});
106	    blockIds.add(block.id);
107	  });
108	  if (input.request.pages !== null && (input.request.form === "first_deliverable" || input.request.form === null)) context.addIssue({code: "custom", path: ["request", "pages"], message: "the first deliverable has no page plan; pages belong to a material form"});
109	});
110	export type BriefInput = z.input<typeof briefInputSchema>;
111	
112	type Kind = (typeof objectKinds)[number];
113	type Stance = "for" | "against" | "neutral";
114	const BLOCKS: Array<{id: string; label: string; needs: Kind[]; stance: Stance | null}> = [
115	  {id: "company_view", label: "Visão da companhia", needs: ["company_view"], stance: null},
116	  {id: "performance_outlook", label: "Desempenho histórico e outlook", needs: ["performance"], stance: null},
117	  {id: "debt_by_instrument", label: "Dívida por instrumento", needs: ["debt_ledger"], stance: null},
118	  {id: "maturity_schedule", label: "Cronograma de vencimentos", needs: ["maturity_wall"], stance: null},
119	  {id: "liquidity_coverage", label: "Liquidez e cobertura", needs: ["maturity_wall", "interest_schedule"], stance: null},
120	  {id: "assumptions", label: "Premissas preliminares", needs: ["scenarios"], stance: null},
121	  {id: "points_for_thesis", label: "Pontos que sustentam a tese", needs: [], stance: "for"},
122	  {id: "points_against_thesis", label: "Pontos contra a tese", needs: [], stance: "against"},
123	  {id: "initial_alternatives", label: "Alternativas iniciais", needs: ["before_after"], stance: null},
124	  {id: "open_questions", label: "Perguntas pendentes", needs: [], stance: null},
125	  {id: "exhibits", label: "Exhibits preliminares", needs: ["debt_ledger", "maturity_wall"], stance: null},
126	];
127	
128	const PAGE_PLANS: Record<"pitch_pages" | "internal_briefing" | "analysis_with_scenarios" | "board_deck", Array<{title: string; blocks: string[]}>> = {
129	  pitch_pages: [
130	    {title: "Situação atual", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage", "points_against_thesis"]},
131	    {title: "Alternativas", blocks: ["initial_alternatives", "points_for_thesis"]},
132	    {title: "Impacto nos indicadores", blocks: ["assumptions", "exhibits"]},
133	  ],
134	  internal_briefing: [{title: "Briefing", blocks: ["company_view", "performance_outlook", "debt_by_instrument", "maturity_schedule", "points_for_thesis", "points_against_thesis", "open_questions"]}],
135	  analysis_with_scenarios: [{title: "Análise", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage"]}, {title: "Cenários", blocks: ["assumptions", "initial_alternatives"]}],
136	  board_deck: [{title: "Contexto", blocks: ["company_view", "performance_outlook"]}, {title: "Estrutura de capital", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage"]}, {title: "Alternativas e decisão", blocks: ["initial_alternatives", "points_for_thesis", "points_against_thesis"]}],
137	};
138	
139	type Block = {id: string; label: string; state: "filled" | "gap"; object_ids: string[]; pending_object_ids: string[]; headlines: Array<{text: string; unit: string | null; object_id: string; object_fingerprint: string; object_path: string | null}>; gap: string | null};
140	type Page = {number: number; title: string; blocks: string[]};
141	export type BriefOutput = {
142	  schema_version: "method.plan-meeting-brief.v4";
143	  case_id: string;
144	  turn: number;
145	  state: "planned" | "awaiting_confirmation";
146	  /** objects_used lists only the objects a filled block cites; usable objects without facts are listed apart. */
147	  deliverable: {blocks: Block[]; objects_used: string[]; objects_usable_not_cited: string[]; objects_pending: Array<{id: string; state: string}>; objects_excluded: Array<{id: string; state: string}>};
148	  page_plan: {state: "not_requested" | "awaiting_audience_and_form" | "proposed" | "confirmed" | "unsupported"; id: string | null; form: string | null; audience: {primary: string; others: string[]} | null; pages: Page[]; discriminator: string | null; production_allowed: boolean; reason: string | null};
149	  alignment_questions: Array<{id: string; text: string; changes_the_work: string}>;
150	  refused_questions: Array<{id: string; reason: string; answered_by: Anchor | null}>;
151	  /** What this executor does not produce: the prose of the pages is a model step downstream of the confirmed plan. */
152	  not_produced_here: string[];
153	  ambiguity_named: string | null;
154	  change_note: {previous_output_fingerprint: string; changes: string[]} | null;
155	  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
156	  trace: {inputFingerprint: string; outputFingerprint: string};
157	};
158	
159	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
160	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
161	const TRIVIAL_REASON = /^(nenhuma|nenhum|none|n\/?a|nada|-)$/i;
162	
163	/** Fits the base layout to the pages asked: merges the tail when fewer, splits the fullest page when more. */
164	function fitPages(base: Array<{title: string; blocks: string[]}>, pages: number | null): Array<{title: string; blocks: string[]}> | null {
165	  const layout = base.map((page) => ({title: page.title, blocks: [...page.blocks]}));
166	  if (pages === null || pages === layout.length) return layout;
167	  if (pages < layout.length) {
168	    while (layout.length > pages) {
169	      const last = layout.pop()!;
170	      const previous = layout[layout.length - 1]!;
171	      previous.title = `${previous.title} e ${last.title.toLowerCase()}`;
172	      previous.blocks.push(...last.blocks);
173	    }
174	    return layout;
175	  }
176	  const totalBlocks = layout.reduce((sum, page) => sum + page.blocks.length, 0);
177	  if (pages > totalBlocks) return null;
178	  while (layout.length < pages) {
179	    const index = layout.reduce((best, page, position) => (page.blocks.length > layout[best]!.blocks.length ? position : best), 0);
180	    const page = layout[index]!;
181	    const half = Math.ceil(page.blocks.length / 2);
182	    layout.splice(index + 1, 0, {title: `${page.title} (continuação)`, blocks: page.blocks.slice(half)});
183	    page.blocks = page.blocks.slice(0, half);
184	  }
185	  return layout;
186	}
187	
188	export function planMeetingBrief(raw: BriefInput): BriefOutput {
189	  const parsed = briefInputSchema.parse(raw);
190	  const input = {...parsed, request: {...parsed.request, audience: parsed.request.audience ? {primary: parsed.request.audience.primary, others: [...parsed.request.audience.others].sort(compare)} : null, undefinedAspects: [...parsed.request.undefinedAspects].sort(compare)}, objects: [...parsed.objects].sort((a, b) => compare(a.id, b.id)).map((object) => ({...object, headlines: [...object.headlines].sort((a, b) => compare(a.text, b.text) || compare(a.stance, b.stance) || compare(a.unit ?? "", b.unit ?? ""))})), candidateQuestions: [...parsed.candidateQuestions].sort((a, b) => a.priority - b.priority || compare(a.id, b.id)), previousVersion: parsed.previousVersion ? {...parsed.previousVersion, blocks: [...parsed.previousVersion.blocks].sort((a, b) => compare(a.id, b.id)).map((block) => ({...block, objectIds: [...block.objectIds].sort(compare)}))} : null};
191	  const usable = input.objects.filter((object) => USABLE_STATES.has(object.state));
192	  const pending = input.objects.filter((object) => !USABLE_STATES.has(object.state) && object.state !== "blocked");
193	  const excluded = input.objects.filter((object) => object.state === "blocked");
194	  const byKind = new Map<Kind, typeof usable>();
195	  for (const object of usable) byKind.set(object.kind, [...(byKind.get(object.kind) ?? []), object]);
196	  const pendingByKind = new Map<Kind, typeof pending>();
197	  for (const object of pending) pendingByKind.set(object.kind, [...(pendingByKind.get(object.kind) ?? []), object]);
198	
199	  const refused: BriefOutput["refused_questions"] = [];
200	  const askable: typeof input.candidateQuestions = [];
201	  for (const question of input.candidateQuestions) {
202	    if (question.coverage?.answer) refused.push({id: question.id, reason: `the base already answers it: ${question.coverage.answer}`, answered_by: question.coverage.answeredBy});
203	    else if (!question.coverage) refused.push({id: question.id, reason: "no search of the base is declared for this question; a question is asked only after the documents were checked and found silent", answered_by: null});
204	    else if (TRIVIAL_REASON.test(question.changesTheWork.trim())) refused.push({id: question.id, reason: "the answer does not change the work", answered_by: null});
205	    else askable.push(question);
206	  }
207	  const asked = askable.slice(0, 3).map((question) => ({id: question.id, text: question.text, changes_the_work: question.changesTheWork}));
208	  for (const question of askable.slice(3)) refused.push({id: question.id, reason: "beyond the three questions that change the work most; kept for a later turn", answered_by: null});
209	
210	  const blocks: Block[] = BLOCKS.map((block) => {
211	    if (block.id === "open_questions") {
212	      return {id: block.id, label: block.label, state: asked.length > 0 ? "filled" : "gap", object_ids: [], pending_object_ids: [], headlines: asked.map((question) => ({text: question.text, unit: null, object_id: `question:${question.id}`, object_fingerprint: fingerprint(question), object_path: null})), gap: asked.length > 0 ? null : "no question that changes the work remains"};
213	    }
214	    // A stance block draws on every usable object that declared the stance; a kind never decides the side.
215	    const found = block.stance !== null ? usable : block.needs.flatMap((kind) => byKind.get(kind) ?? []);
216	    const waiting = block.stance !== null ? pending.filter((object) => object.headlines.some((headline) => headline.stance === block.stance)) : block.needs.flatMap((kind) => pendingByKind.get(kind) ?? []);
217	    const headlines = found.flatMap((object) => object.headlines.filter((headline) => block.stance === null || headline.stance === block.stance).map((headline) => ({text: headline.text, unit: headline.unit, object_id: object.id, object_fingerprint: headline.objectFingerprint, object_path: headline.objectPath})));
218	    if (block.stance !== null) {
219	      if (headlines.length === 0) return {id: block.id, label: block.label, state: "gap", object_ids: [], pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `no usable object states a point ${block.stance} the thesis${waiting.length > 0 ? `; ${waiting.map((object) => `${object.id} is ${object.state}`).join(", ")}` : ""}`};
220	      return {id: block.id, label: block.label, state: "filled", object_ids: found.filter((object) => object.headlines.some((headline) => headline.stance === block.stance)).map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines, gap: null};
221	    }
222	    const missing = block.needs.filter((kind) => !byKind.has(kind));
223	    if (missing.length > 0) {
224	      const reasons = missing.map((kind) => { const held = pendingByKind.get(kind) ?? []; return held.length > 0 ? `${kind}: ${held.map((object) => `${object.id} is ${object.state}`).join(", ")}` : `no usable object of kind ${kind}`; });
225	      return {id: block.id, label: block.label, state: "gap", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `${reasons.join("; ")}; the block is named as a gap, not written`};
226	    }
227	    if (headlines.length === 0) return {id: block.id, label: block.label, state: "gap", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines: [], gap: `${found.map((object) => object.id).join(", ")} usable but without facts to cite; a block is filled with facts, not with an object id`};
228	    return {id: block.id, label: block.label, state: "filled", object_ids: found.map((object) => object.id), pending_object_ids: waiting.map((object) => object.id), headlines, gap: null};
229	  });
230	
231	  const audience = input.request.audience;
232	  let pagePlan: BriefOutput["page_plan"] = {state: "not_requested", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: "the first deliverable is not a material; the page plan waits for the audience and the form"};
233	  if (audience === null || input.request.form === null) pagePlan = {state: "awaiting_audience_and_form", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: `the deliverable goes out; the page plan waits for ${[audience === null ? "the audience" : null, input.request.form === null ? "the form" : null].filter(Boolean).join(" and ")}`};
234	  else if (input.request.form !== "first_deliverable") {
235	    const layout = fitPages(PAGE_PLANS[input.request.form], input.request.pages);
236	    if (!layout) pagePlan = {state: "unsupported", id: null, form: input.request.form, audience, pages: [], discriminator: null, production_allowed: false, reason: `${input.request.pages} pages exceed the blocks the form ${input.request.form} carries; ask the person which blocks the extra pages should hold`};
237	    else {
238	      const pages: Page[] = layout.map((page, index) => ({number: index + 1, title: page.title, blocks: page.blocks}));
239	      const discriminator = `what changes the decision of ${audience.primary} comes first${audience.others.length > 0 ? `; ${audience.others.join(", ")} read the same pages` : ""}`;
240	      const planId = fingerprint({form: input.request.form, audience, pages, discriminator});
241	      const confirmed = input.request.confirmedPlanId === planId;
242	      pagePlan = {state: confirmed ? "confirmed" : "proposed", id: planId, form: input.request.form, audience, pages, discriminator, production_allowed: confirmed, reason: confirmed ? null : input.request.confirmedPlanId ? "the confirmed plan differs from this one; production waits for the person to confirm this plan" : "production waits for the person to confirm the plan"};
243	    }
244	  }
245	
246	  const aspects: Record<string, string> = {thesis: "which thesis to carry", meeting_type: "whether the meeting explores or tests a product", format: "which format is expected", audience: "who the material is for", depth: "how deep the material goes"};
247	  const ambiguityNamed = input.request.undefinedAspects.length > 0 ? `the sponsor's instruction leaves undefined: ${input.request.undefinedAspects.map((aspect) => aspects[aspect]).join("; ")}. The deliverable says so and starts the work anyway` : null;
248	
249	  let changeNote: BriefOutput["change_note"] = null;
250	  if (input.previousVersion) {
251	    const changes: string[] = [];
252	    for (const block of blocks) {
253	      const previous = input.previousVersion.blocks.find((entry) => entry.id === block.id);
254	      if (!previous) changes.push(`block ${block.id} is new`);
255	      else if (previous.state !== block.state) changes.push(`block ${block.id} moved from ${previous.state} to ${block.state}`);
256	      else if (stableStringify(previous.objectIds) !== stableStringify(block.object_ids)) changes.push(`block ${block.id} now cites ${block.object_ids.join(", ") || "nothing"} instead of ${previous.objectIds.join(", ") || "nothing"}`);
257	    }
258	    for (const object of input.objects) {
259	      const before = input.previousVersion.objectFingerprints[object.id];
260	      if (before === undefined) changes.push(`object ${object.id} entered since the previous version`);
261	      else if (before !== object.fingerprint) changes.push(`object ${object.id} changed (premise or number) since the previous version: ${before.slice(0, 12)} to ${object.fingerprint.slice(0, 12)}`);
262	    }
263	    for (const id of Object.keys(input.previousVersion.objectFingerprints).sort(compare)) if (!input.objects.some((object) => object.id === id)) changes.push(`object ${id} left since the previous version`);
264	    changeNote = {previous_output_fingerprint: input.previousVersion.outputFingerprint, changes};
265	  }
266	
267	  const uncovered = [
268	    ...blocks.filter((block) => block.state === "gap" && block.id !== "open_questions").map((block) => ({id: block.id, state: "insufficient_evidence" as const, reason: block.gap!})),
269	    ...pending.map((object) => ({id: `object:${object.id}`, state: "insufficient_evidence" as const, reason: `${object.id} (${object.kind}) is ${object.state}; its findings are carried as conditions and not written into the deliverable: ${object.headlines.map((headline) => headline.text).join("; ") || "no facts declared"}`})),
270	  ];
271	  const body = {
272	    schema_version: "method.plan-meeting-brief.v4" as const,
273	    case_id: input.caseId,
274	    turn: input.request.turn,
275	    state: pagePlan.state === "proposed" ? "awaiting_confirmation" as const : "planned" as const,
